<style>
.notes-studio{max-width:1440px;margin:auto;padding:24px;--notes-ink:var(--text-primary,#172033)}.notes-hero{display:flex;justify-content:space-between;gap:20px;align-items:center;padding:28px;border:1px solid var(--border-glass);border-radius:24px;background:linear-gradient(125deg,#365ce912,#9333ea0a,var(--bg-card,#ffffff));margin-bottom:20px}.notes-hero h1{font-size:30px;font-weight:800;color:var(--notes-ink)}.notes-hero p{color:var(--text-muted);margin-top:6px}.notes-grid{display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:24px;align-items:start}.notes-card{border:1px solid var(--border-glass);border-radius:22px;padding:24px;background:var(--bg-card,#ffffff);min-width:0}.notes-card h2{font-weight:750;font-size:18px;margin-bottom:12px}.notes-card p,.notes-card li{overflow-wrap:anywhere}.notes-label{display:block;font-size:12px;font-weight:650;margin-bottom:8px;color:var(--text-secondary)}.notes-columns{display:grid;grid-template-columns:1fr 1fr;gap:16px}.notes-hint{font-size:12px;color:var(--text-muted);line-height:1.6}.notes-studio textarea{color:var(--notes-ink);resize:vertical}.notes-studio .theme-input{min-width:0;width:100%}.notes-stack{display:grid;gap:20px}.notes-purpose{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:18px}.notes-purpose button{font-size:12px;border:1px solid var(--border-glass);border-radius:12px;padding:10px 12px;color:var(--text-secondary)}.notes-purpose button[aria-pressed=true]{background:#365ce9;color:white;border-color:#365ce9}.notes-wallet{text-align:right;flex-shrink:0}.notes-wallet strong{font-size:24px;color:#365ce9}.notes-metric{border-radius:18px;padding:18px;color:white;background:linear-gradient(135deg,#16428a,#347cff)}.notes-metric:nth-child(2){background:linear-gradient(135deg,#542c8c,#935def)}.notes-metric:nth-child(3){background:linear-gradient(135deg,#075b54,#119a88)}.notes-metric strong{font-size:30px;display:block}.notes-metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.notes-history a{display:block;padding:14px 0;border-bottom:1px solid var(--border-glass);color:var(--notes-ink)}.notes-history small{display:block;color:var(--text-muted);margin-top:4px}.notes-task{border:1px solid var(--border-glass);border-radius:16px;padding:16px;display:grid;gap:10px}.notes-task-head{display:flex;gap:10px;justify-content:space-between;align-items:start}.notes-priority{border-radius:8px;padding:4px 8px;font-size:11px;background:#365ce918;color:var(--text-secondary);flex-shrink:0}.notes-actions{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.notes-source{background:var(--bg-input,var(--bg-card,#ffffff));padding:16px;border-radius:16px}.notes-modal{position:fixed;inset:0;background:#0f172a80;z-index:100;display:flex;align-items:center;justify-content:center;padding:20px}.notes-modal .notes-card{width:100%;max-width:520px;max-height:90vh;overflow:auto;background:var(--bg-card,#ffffff)}.notes-result{white-space:pre-wrap;line-height:1.65}.notes-studio details summary{cursor:pointer;font-weight:650}.notes-history{position:sticky;top:100px}.notes-example{font-size:12px;color:#365ce9;text-align:left}.notes-quote{border-radius:12px;background:#365ce910;padding:12px;font-size:13px}.notes-studio .form-chip{border:1px solid var(--border-glass,#dbe1ec);border-radius:12px;padding:10px 14px;background:var(--bg-card,#fff);color:var(--text-secondary,#334155);font-size:13px;display:inline-flex;align-items:center;justify-content:center;gap:6px}.notes-studio button:disabled{opacity:.5;cursor:not-allowed}
@media(max-width:1050px){.notes-grid{grid-template-columns:1fr}.notes-history{position:static}}@media(max-width:640px){.notes-studio{padding:12px}.notes-hero{padding:20px;align-items:start}.notes-hero h1{font-size:23px}.notes-wallet strong{font-size:18px}.notes-card{padding:18px}.notes-columns{grid-template-columns:1fr}.notes-metrics{gap:8px}.notes-metric{padding:12px}.notes-metric strong{font-size:24px}}
</style>